<div class="page-head"><div><h3>Monthly stock</h3><p>Opening and month-end physical stock by material.</p></div><form class="month-form"><input type="month" name="month" value="<?= esc($month) ?>"><button class="primary">Apply</button></form></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Material</th><th>Opening</th><th>Receipts</th><th>Issued</th><th>Calculated Closing</th><th>Physical</th><th>Difference</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= esc($r['code']) ?></b><small><?= esc($r['description']) ?></small></td><td><?= number_format($r['opening_stock'],3) ?></td><td><?= number_format($r['closing_stock']-$r['opening_stock']+$r['issued_qty']??0,3) ?></td><td><?= number_format($r['issued_qty']??0,3) ?></td><td><b><?= number_format($r['closing_stock'],3) ?></b></td><td><?= $r['physical_stock_month_end']===null?'—':number_format($r['physical_stock_month_end'],3) ?></td><td><?= $r['physical_stock_month_end']===null?'—':number_format($r['difference'],3) ?></td></tr><?php endforeach; ?></tbody></table></div></section>